<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany;
class Advocate extends Model { use HasFactory,SoftDeletes; protected $fillable=['user_id','name','slug','title','bio','email','phone','photo_path','is_active','sort_order']; protected function casts(): array{return ['is_active'=>'boolean'];} public function user(): BelongsTo{return $this->belongsTo(User::class);} public function practiceAreas(): BelongsToMany{return $this->belongsToMany(PracticeArea::class);} public function consultations(): HasMany{return $this->hasMany(Consultation::class);} }
